// Route audit submission to the correct industry Notion vault database
// and prepare all data for page creation, template population, and notifications.

const data = $input.item.json;
const industry = data.industry || 'home-services';
const businessName = data.business_name || 'Unknown Business';
const customerName = data.customer_name || 'Valued Client';
const customerEmail = data.customer_email || '';
const market = data.market || 'raleigh';
const timestamp = data.timestamp || new Date().toISOString();
const auditDate = timestamp.split('T')[0];

// Industry -> Notion Database ID routing (PRD Section 2.5)
const databaseMap = {
  'medspa':        '3f5c3ac39e9d44e1b89558c89eb299bb',
  'realtor':       '81c5f71a1492451bb9afa5a95b1bd39f',
  'law':           '3952b5325c5345d1a972d33e2a54c74b',
  'home-services': 'ef81056d84554e1f9cbdb46a949b6535'
};

const industryLabels = {
  'medspa': 'Med Spa',
  'realtor': 'Real Estate',
  'law': 'Law',
  'home-services': 'Home Services'
};

const marketLabels = {
  'raleigh': 'Raleigh',
  'columbus': 'Columbus',
  'moscow': 'Moscow'
};

const divisionMap = {
  'medspa': 'Creative',
  'realtor': 'Creative',
  'law': 'Automations',
  'home-services': 'Automations'
};

const targetDb = databaseMap[industry] || databaseMap['home-services'];
const industryLabel = industryLabels[industry] || 'Home Services';
const marketLabel = marketLabels[market] || 'Raleigh';
const division = divisionMap[industry] || 'Automations';
const pageTitle = `${industryLabel} - ${businessName} - Audit ${auditDate}`;
const assetScore = parseInt(data.asset_score) || 0;
const paidTraffic = (data.paid_traffic || '').toLowerCase() === 'yes';

// Pre-Audit Report: Industry-specific findings (conditional on division)
let findingsHeading, finding1, finding2, finding3;
if (division === 'Creative') {
  findingsHeading = `For LNL Creative (${industryLabel})`;
  finding1 = 'Visual Friction: Identify where high-end clients are being turned off by low-quality assets or inconsistent branding.';
  finding2 = 'Conversion Gaps: Pinpoint the exact moment a lead stops clicking in the current funnel.';
  finding3 = 'Cinematic Potential: Highlight 1-2 raw clips the client uploaded and explain the LNL Refresh to apply.';
} else {
  findingsHeading = `For LNL Automations (${industryLabel})`;
  finding1 = 'Manual Bottlenecks: List the specific tasks (Intake, Invoicing, Dispatch) currently consuming human time.';
  finding2 = 'Tech Overlap: Identify Ghost Apps they are paying for that duplicate functionality in their stack.';
  finding3 = 'Speed-to-Lead Audit: Show exactly how many minutes/hours pass before a lead gets a response vs. the industry standard (under 5 mins).';
}

// Division-specific vault client checklist
let checklist1, checklist2, checklist3;
if (division === 'Creative') {
  checklist1 = 'Logo & Brand Kit: High-resolution files for visual alignment audit.';
  checklist2 = 'Active Ad Creative: Screenshots or files of currently running Meta/Google ads.';
  checklist3 = 'Top 3 Social Posts: Best-performing content for hooks/engagement analysis.';
} else {
  checklist1 = 'Software Inventory: A list or screenshot of all monthly tech subscriptions.';
  checklist2 = 'Intake/Lead Logs: An export of last 10 leads to audit Speed to Lead.';
  checklist3 = 'Sample Service Agreement: A blank contract or invoice for document-automation review.';
}

// Pre-formatted diagnostic snapshot for the Notion page body
const diagnosticSnapshot = [
  'DIAGNOSTIC SNAPSHOT',
  `- Competitor Insight: ${data.competitor_reason || 'Not provided'}`,
  `- Content Effort: ${data.content_hours || 'Not specified'} hrs/week`,
  `- Self-Assessed Visual Score: ${assetScore}/10`,
  `- Content Library: ${data.content_library || 'Not specified'}`,
  `- Lead Journey: ${data.lead_next_step || 'Not specified'}`,
  `- Paid Traffic: ${data.paid_traffic || 'No'} | CPL: ${data.cpl || 'N/A'}`,
  `- Tech Stack: ${data.tech_stack || 'Not specified'}`
].join('\n');

return {
  ...data,
  target_db: targetDb,
  industry_label: industryLabel,
  market_label: marketLabel,
  division: division,
  page_title: pageTitle,
  audit_date: auditDate,
  asset_score_num: assetScore,
  paid_traffic_bool: paidTraffic,
  findings_heading: findingsHeading,
  finding_1: finding1,
  finding_2: finding2,
  finding_3: finding3,
  checklist_1: checklist1,
  checklist_2: checklist2,
  checklist_3: checklist3,
  diagnostic_snapshot: diagnosticSnapshot
};
